contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with a parameter to vary (unused value but satisfies requirement)
    function run(uint dummy) public payable {
        // observe before values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        // perform the state-changing call as the owner: withdrawAll()
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: if withdrawAll reverted then nothing changed; otherwise balance becomes zero and depositsCount did not decrease
        assert(reverted ? (afterCount == beforeCount && afterBal == beforeBal) : (afterBal == 0 && afterCount >= beforeCount));
    }

    receive() external payable {}
}

